// Fast floor division by 86400.
// (rounds towards negative infinity).
// Accurate over the full signed 32-bit range.
// Round-down multiplier (forced).
// Optional ref:
// https://www.benjoffe.com/fast-floordiv#fn=i32_86400
inline int32_t fast_i32_floordiv_86400(int32_t x) {
 const int32_t M = ((1ll << 47) / 86400); // 1628906115
 const int32_t t = x + (uint32_t(x) < 0x7FFFFFFF);
 return (int64_t) t * M >> 47;
}
